export function Mark({ size = 34, mono, active }: { size?: number; mono?: string; active?: Discipline[] }) {
  return (
    <svg width={size} height={size} viewBox="-142 -142 284 284" aria-hidden className="mark">
      {(Object.keys(MARK) as Discipline[]).map((k) => (
        <path key={k} d={MARK[k]} fill={mono ?? DISCIPLINE_COLOR[k]} data-off={active && !active.includes(k) ? "" : undefined} />
      ))}
    </svg>
  );
}

export function Wordmark({ height = 24, color = "var(--purple)" }: { height?: number; color?: string }) {
  return (
    <svg height={height} width={Math.round((height * 968) / 218)} viewBox="4 4 968 218" aria-hidden>
      <path d={WORD} fill={color} fillRule="evenodd" />
    </svg>
  );
}

export default function Logo({ mono }: { mono?: string }) {
  return (
    <span className="logo">
      <Mark size={38} mono={mono} />
      <Wordmark height={26} color={mono} />
    </span>
  );
}
